#include <bits/stdc++.h>
using namespace std;

struct MathUtils {
    static long long inverse(long long a, long long mod) {
        auto inv = extended_gcd(a, mod);
        if (inv[0] != 1) {
            return 0;
        } else {
            return (inv[1] % mod + 2 * mod) % mod;
        }
    }

    static long long modFraction(long long a, long long b, long long mod) {
        long long invB = inverse(b, mod);
        if (invB == 0) {
            return -1;
        } else {
            return (invB * a) % mod;
        }
    }

    static std::vector<long long> extended_gcd(long long a, long long b) {
        if (a == 0) return {b, 0, 1};
        auto next = extended_gcd(b % a, a);
        long long x = next[1];
        next[1] = next[2] - (b / a) * next[1];
        next[2] = x;
        return next;
    }

    static long long mod(long long a, long long m) {
        return ((a % m) + m) % m;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M, K;
    cin >> N >> M >> K;
    const long long MOD = 998244353;
    long long modFraction = MathUtils::modFraction(1, M, MOD);
    vector<long long> expect(K + 1, 0);
    vector<long long> poly(K + 1, 0);
    expect[0] = 1;
    poly[0] = 1;
    long long curExpect = 1;

    for (int k = 1; k <= K; ++k) {
        long long temp = 1;
        for (int i = 0; i < k; ++i) {
            temp = (temp * (N - i)) % MOD;
        }
        curExpect = (temp * modFraction) % MOD;
        for (int i = k; i >= 0; --i) {
            long long val = (i > 0 ? poly[i - 1] : 0) - (k - 1) * poly[i];
            poly[i] = MathUtils::mod(val, MOD);
        }
        expect[k] = curExpect;
        for (int i = k - 1; i >= 0; --i) {
            long long val = expect[k] - poly[i] * expect[i];
            expect[k] = MathUtils::mod(val, MOD);
        }
    }
    cout << expect[K] << "\n";
    return 0;
}

